/* Session-global rule editing with immutable official defaults and opt-in named profiles. */
const RuleWorkspace=(function(){
'use strict';
let baseConfig,official,current,draft,maps={},priorityCSV='',profiles=[],preview=null,undo=null,installed=false;
const clone=RuleProfiles.copy;
const material=p=>JSON.stringify([p?.name,p?.settings,p?.documents,p?.industryAliases,p?.companyAliasesExtra,p?.countryAliases,p?.nationalityAliases,p?.departmentTargets]);
const batchSignature=()=>JSON.stringify([D.units,G,log.length]);
const isDefault=p=>material(p)===material(official);
function setDraft(p){draft=clone(p);maps=Object.fromEntries(['industryAliases','companyAliasesExtra','countryAliases','nationalityAliases','departmentTargets'].map(k=>[k,JSON.stringify(draft[k],null,2)]));priorityCSV=draft.settings.naturePriority.join(',');preview=null;ruleIndex=Math.min(ruleIndex,draft.documents.length-1)}
async function profileStore(value){const db=await batchDB();try{return await new Promise((resolve,reject)=>{const tx=db.transaction('workspace',value===undefined?'readonly':'readwrite'),s=tx.objectStore('workspace'),r=value===undefined?s.get('rule-profiles'):s.put(value,'rule-profiles');tx.oncomplete=()=>resolve(r.result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}finally{db.close()}}
function initialize(cfg,def){baseConfig=clone(cfg);official=RuleProfiles.validate(def);current=clone(official);setDraft(official);profiles=[];profileStore().then(saved=>{profiles=Array.isArray(saved)?saved:[];if(view==='rules')render()}).catch(()=>{});return current}
function prepareBatch(data,backup){
 const originalBase=backup?.baseGuests||clone(data.guests),metadata={edits:backup?.edits||{},reviewed:backup?.reviewed||{},log:backup?.log||[]};
 if(material(data.ruleProfile)===material(current)&&data.processing?.version===current.version)return{data,backup};
 const rebuilt=RuleRebuild.rebuild(data,originalBase,current,baseConfig,metadata);
 return{data:rebuilt.data,backup:{...metadata,baseGuests:rebuilt.baseGuests,edits:rebuilt.edits,reviewed:rebuilt.reviewed}};
}
function resetLoadedBatch(){const r=prepareBatch(D,{baseGuests:baseG,edits,reviewed,log});D=r.data;G=D.guests;U=new Map(D.units.map(u=>[u.id,u]));if(r.backup){baseG=r.backup.baseGuests;edits=r.backup.edits;reviewed=r.backup.reviewed}D.ruleProfile=clone(current);D.rules=clone(current.documents)}
function readDraft(){const p=clone(draft);p.settings.naturePriority=priorityCSV.split(/[,，\s]+/).filter(Boolean).map(Number);for(const k of Object.keys(maps)){try{p[k]=JSON.parse(maps[k])}catch{throw Error(k+'不是有效JSON对象')}}if(material(p)!==material(official)){if(p.name.trim()===official.name)p.name='用户临时方案';p.version='user-'+new Date().toISOString();p.updatedAt=new Date().toISOString()}else p.version=official.version;return RuleProfiles.validate(p)}
function counts(data){const s=data.ruleProfile?.settings||RuleProfiles.settings,gs=data.guests;return[...['confirmed','included'].map(k=>new Set(gs.filter(g=>k==='confirmed'?RuleProfiles.confirmed(g.status,s):RuleProfiles.included(g.status,s)).map(g=>g.unitId)).size),gs.filter(g=>RuleProfiles.confirmed(g.status,s)).length,gs.filter(g=>RuleProfiles.included(g.status,s)).length,gs.filter(g=>g.priority).length,gs.filter(g=>g.priorityCandidate).length,gs.filter(g=>g.senior).length]}
function previewRules(p){const before=counts({...D,guests:G});const rebuilt=RuleRebuild.rebuild({...D,guests:G},baseG,p,baseConfig,{edits,reviewed,log});preview={profile:p,rebuilt,before,after:counts(rebuilt.data),batchSignature:batchSignature()};return preview}
function applyPreview(){if(!preview)throw Error('请先预览规则影响');if(preview.batchSignature!==batchSignature())throw Error('批次已变化，请重新预览');const p=preview;undo={data:clone({...D,guests:G}),baseGuests:clone(baseG),edits:clone(edits),reviewed:clone(reviewed),log:clone(log),profile:clone(current)};current=clone(p.profile);processor=Processing.create(RuleProfiles.config(baseConfig,current));D=p.rebuilt.data;G=D.guests;U=new Map(D.units.map(u=>[u.id,u]));baseG=p.rebuilt.baseGuests;edits=p.rebuilt.edits;reviewed=p.rebuilt.reviewed;log.push({time:new Date().toISOString(),action:'rule-profile-apply',profileName:current.name,version:current.version,before:p.before,after:p.after,warnings:p.rebuilt.warnings});D.ruleProfile=clone(current);D.rules=clone(current.documents);preview=null;setDraft(current);save();updateBatchLabel();render();toast('已应用到本次会话全部统计、名单、后续导入和导出')}
function restorePrevious(){if(!undo)throw Error('本次会话没有可恢复的规则应用记录');const u=undo;undo=null;D=u.data;G=D.guests;U=new Map(D.units.map(x=>[x.id,x]));baseG=u.baseGuests;edits=u.edits;reviewed=u.reviewed;log=u.log;current=u.profile;processor=Processing.create(RuleProfiles.config(baseConfig,current));setDraft(current);save();updateBatchLabel();render();toast('已恢复上次应用规则前的批次和方案')}
const select=(key,label,choices)=>`<label class="form-field">${label}<select data-rule-setting="${key}">${choices.map(([v,t])=>`<option value="${v}" ${draft.settings[key]===v?'selected':''}>${t}</option>`).join('')}</select></label>`;
const bool=(key,label)=>`<label style="display:block;margin:10px 0"><input type="checkbox" data-rule-bool="${key}" ${draft.settings[key]?'checked':''}> ${label}</label>`;
const list=(key,label,choices)=>`<div style="margin:15px 0"><b>${label}</b>${choices.map(([v,t])=>`<label style="display:block;margin:6px 0"><input type="checkbox" data-rule-list="${key}" value="${v}" ${draft.settings[key].includes(v)?'checked':''} ${key==='priorityRequiredFields'&&['name','title'].includes(v)?'disabled':''}> ${t}</label>`).join('')}</div>`;
const modeChoices=[['provisional','暂计，单独披露'],['confirmed','计入当前确认口径'],['exclude','不计入参会范围']];
function renderRulePage(){
 if(!draft)return header('统计规则','正在加载敲定默认规则…');ruleIndex=Math.max(0,Math.min(ruleIndex,draft.documents.length-1));
 const labels=['确认单位','含暂计单位','确认嘉宾','含暂计嘉宾','重点已入选','重点候选','当前高管口径'];
 return header('统计规则','敲定默认版只读保留；编辑、预览后应用本次会话全局')+`<div class="notice">当前应用：<b>${esc(current.name)}</b> · ${esc(current.version)}。${isDefault(current)?'敲定默认口径':'用户自定义口径'}。每次重新打开恢复默认，不自动启用另存方案；作用范围是本浏览器本次会话，不会修改其他使用者。</div><section class="panel"><div class="panel-body"><h2>规则方案</h2><label class="form-field">编辑中的方案名称<input id="rule-profile-name" value="${esc(draft.name)}" maxlength="80"></label><div class="actions"><button class="btn primary" data-action="rules-preview">预览规则影响</button><button class="btn" data-action="rules-save">另存为本机方案</button><button class="btn" data-action="rules-export">导出编辑方案JSON</button><button class="btn" data-action="rules-default">恢复并应用敲定默认版</button>${undo?'<button class="btn" data-action="rules-undo">撤回上次规则应用</button>':''}</div><label class="form-field">已另存的本机方案<select id="rule-profile-list"><option value="">请选择，载入不会立即生效</option>${profiles.map((p,i)=>`<option value="${i}">${esc(p.profile.name)} · ${esc(p.savedAt)}</option>`).join('')}</select></label><button class="btn" data-action="rules-load">载入所选方案到编辑区</button><label class="form-field">导入规则方案JSON<input id="rule-profile-import" type="file" accept=".json"></label><p class="tiny">另存不等于应用；载入后仍需预览并应用。规则JSON只包含规则和对照，不包含参会名单。完整工作进度请另存批次备份。</p></div></section>${preview?`<section class="panel" id="rule-preview" style="margin-top:20px"><div class="panel-body"><h2>规则影响预览 · 尚未应用</h2>${table(['统计项','当前','应用后','变化'],labels.map((l,i)=>[l,preview.before[i],preview.after[i],preview.after[i]-preview.before[i]]))}<p>${esc(preview.rebuilt.warnings.join('；')||'按原始来源保留可对应的核对修改；归并关系变化时请检查明细。')}</p><button class="btn primary" data-action="rules-apply">确认应用到当前会话全局</button></div></section>`:''}<section class="panel" style="margin-top:20px"><div class="panel-body"><h2>详细规则正文</h2><p>包含01—19条已确认口径、全部标准字典、统计影响及重点规则。修改正文只改变说明文字；实际统计由下方可执行参数控制，文字不会被自动编译为算法。新增未支持的判断应作为待核对说明。</p><div class="rule-select">${draft.documents.map((d,i)=>`<button class="btn ${ruleIndex===i?'primary':''}" data-rule="${i}">${esc(d.name.replace('.md',''))}</button>`).join('')}</div><textarea id="rule-document-editor" aria-label="详细规则正文" style="width:100%;min-height:430px;box-sizing:border-box;line-height:1.8">${esc(draft.documents[ruleIndex].text)}</textarea></div></section><section class="panel" style="margin-top:20px"><div class="panel-body"><h2>可执行参数：计数与归并</h2>${select('pendingMode','参会状态待定',modeChoices)}${select('blankMode','参会状态空白',modeChoices)}${bool('mergeNamedGuests','同主体同名嘉宾合并计数')}${bool('mergeAnonymousAcrossOwners','同企业匿名名额跨部门归并')}${bool('useCompanyAliases','使用敲定企业名称对照；关闭后仍保留导入页明确对照')}${select('titleSelection','重复嘉宾职务择一',[['preciseThenDistrict','精准表述优先，职级冲突时区级优先'],['first','按较早原始行保留'],['districtFirst','先取区级来源，再按较早原始行']])}<label class="form-field">企业性质优先级（完整填写1至10，逗号分隔）<input id="rule-nature-priority" value="${esc(priorityCSV)}"></label>${list('worldYears','世界500强年度',[['2025','2025年'],['2026','2026年']])}${bool('usePrivateRanking','启用中国民营企业500强核验')}${bool('cityToChina','国内城市国别映射为中国')}${select('industryConflict','同企业行业冲突',[['pending','列待核对'],['first','采用较早有效记录']])}${select('countryConflict','同企业国别冲突',[['pending','列待核对'],['first','采用较早有效记录']])}</div></section><section class="panel" style="margin-top:20px"><div class="panel-body"><h2>可执行参数：重点与高管</h2>${list('priorityChannels','重点通道',[['A','A 榜单企业'],['B','B 其他企业'],['C','C 机构']])}${list('priorityRoles','同等级职务扩展（关闭后不直接按该扩展纳入；部分仍可列核对候选）',[['state','央国企经营／党委负责人'],['founder','创始人候选'],['foreign','外企主席／中国区负责人'],['partner','合伙人候选及管理合伙人'],['institution','机构负责人']])}${list('priorityRequiredFields','重点必须完整的字段',[['fullName','企业全称'],['short','企业简称'],['type','类型／性质'],['name','嘉宾姓名（必需）'],['title','嘉宾职务（必需）'],['nationality','嘉宾国籍／地区']])}<label class="form-field">原高管口径包含关键词（每行一个，改动会改变高管人数）<textarea data-rule-lines="seniorKeywords" rows="8">${esc(draft.settings.seniorKeywords.join('\n'))}</textarea></label><label class="form-field">原高管口径排除关键词（每行一个）<textarea data-rule-lines="seniorExclusions" rows="5">${esc(draft.settings.seniorExclusions.join('\n'))}</textarea></label></div></section><section class="panel" style="margin-top:20px"><div class="panel-body"><h2>明确同义写法与新增对照</h2><p>填写JSON对象，例如 {"原填值":"标准值"}。不凭相似词自动归并；导入页对该文件明确填写的名称对照优先。</p>${[['industryAliases','行业同义映射'],['companyAliasesExtra','新增企业名称对照'],['countryAliases','单位国别映射'],['nationalityAliases','嘉宾国籍／地区映射'],['departmentTargets','各部门任务指标（JSON数值，例如：{"南山区":100}）']].map(([k,l])=>`<label class="form-field">${l}<textarea data-rule-map="${k}" rows="5">${esc(maps[k])}</textarea></label>`).join('')}<button class="btn primary" data-action="rules-preview">预览规则影响</button></div></section>`;
}
renderRules=renderRulePage;
function editInput(e){const t=e.target;if(!draft)return;let changed=false;
 if(t.id==='rule-profile-name'){draft.name=t.value;changed=true}
 if(t.id==='rule-document-editor'){draft.documents[ruleIndex].text=t.value;changed=true}
 if(t.id==='rule-nature-priority'){priorityCSV=t.value;changed=true}
 if(t.dataset?.ruleSetting){draft.settings[t.dataset.ruleSetting]=t.value;changed=true}
 if(t.dataset?.ruleBool){draft.settings[t.dataset.ruleBool]=t.checked;changed=true}
 if(t.dataset?.ruleList){const k=t.dataset.ruleList,v=t.value;draft.settings[k]=t.checked?[...new Set([...draft.settings[k],v])]:draft.settings[k].filter(x=>x!==v);changed=true}
 if(t.dataset?.ruleLines){draft.settings[t.dataset.ruleLines]=t.value.split('\n').map(x=>x.trim()).filter(Boolean);changed=true}
 if(t.dataset?.ruleMap){maps[t.dataset.ruleMap]=t.value;changed=true}
 if(changed){preview=null;const p=$('#rule-preview');if(p)p.hidden=true}
}
document.addEventListener('input',editInput);document.addEventListener('change',editInput);
document.addEventListener('change',async e=>{if(e.target.id!=='rule-profile-import')return;const f=e.target.files[0];if(!f)return;try{if(f.size>1024*1024)throw Error('规则文件超过1MB');setDraft(RuleProfiles.validate(JSON.parse(await f.text())));render();toast('已载入编辑区，尚未应用')}catch(err){toast('规则导入失败：'+err.message)}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]'),a=b?.dataset.action;if(!a?.startsWith('rules-'))return;
 try{
  if(a==='rules-preview'){toast('正在按编辑方案重算预览…');await new Promise(r=>setTimeout(r,20));previewRules(readDraft());render()}
  if(a==='rules-apply')applyPreview();
  if(a==='rules-default'){previewRules(clone(official));applyPreview()}
  if(a==='rules-undo')restorePrevious();
  if(a==='rules-save'){const p=readDraft();if(p.name===official.name||p.name==='用户临时方案')throw Error('请为自定义方案填写独立名称');const next=[...profiles,{id:Date.now().toString(36)+Math.random().toString(36).slice(2),savedAt:new Date().toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}),profile:p}];if(next.length>25)throw Error('本机最多另存25个方案，请导出规则JSON归档');await profileStore(next);profiles=next;setDraft(p);render();toast('自定义规则已另存到本机，未改变当前应用方案')}
  if(a==='rules-load'){const i=$('#rule-profile-list').value;if(i==='')throw Error('请先选择一个已另存方案');setDraft(RuleProfiles.validate(profiles[+i].profile));render();toast('已载入编辑区，请预览后应用')}
  if(a==='rules-export'){const p=readDraft();Office.download(new Blob([JSON.stringify(p,null,2)],{type:'application/json'}),p.name.replace(/[\\/:*?"<>|]/g,'_')+'_规则方案.json');toast('规则方案JSON已生成')}
 }catch(err){toast('规则操作失败：'+err.message)}
});
function install(){if(installed)return;installed=true;const previous=reportText;reportText=function(){let text=previous();const s=D.ruleProfile?.settings||RuleProfiles.settings;if(JSON.stringify(s.seniorKeywords)!==JSON.stringify(RuleProfiles.settings.seniorKeywords)||JSON.stringify(s.seniorExclusions)!==JSON.stringify(RuleProfiles.settings.seniorExclusions))text=text.replace('总裁及副总裁以上仍按原关键词口径统计，不因本次重点范围扩展而改变。','高管使用当前用户方案关键词统计，可能不同于敲定默认口径。');return text+`\n实际应用方案：${D.ruleProfile?.name||'敲定默认版'}；版本：${D.ruleProfile?.version||official?.version||''}。作用范围：当前使用者本次会话。`};const previousLabel=updateBatchLabel;updateBatchLabel=function(){previousLabel();document.querySelector('footer').innerHTML+=' · 方案 '+esc(D.ruleProfile?.name||'敲定默认版')}}
return{initialize,prepareBatch,resetLoadedBatch,install,getCurrent:()=>clone(current),getOfficial:()=>clone(official),readDraft,previewRules,applyPreview,restorePrevious,counts};
})();
